// The design tokens' mod half (tokens.ts, generated by `cargo xtask tokens`; docs/design/style.md;
// T-B2-10, T-B2-11): every glyph has an ASCII twin and is one column; the roles are theme keys.
import { describe, expect, test } from 'claude-code/testing'

import { GLYPHS, ROLES, glyph } from './tokens'
import type { GlyphName } from './tokens'

describe('T-B2-10, T-B2-11 · glyphs and roles', () => {
  test('each glyph one column, its twin plain ASCII; glyph() picks one or the other', () => {
    for (const [name, [u, a]] of Object.entries(GLYPHS)) {
      expect(Array.from(u).length).toBe(1)
      expect(a).toMatch(/^[\x20-\x7e]+$/)
      expect(glyph(name as GlyphName, false)).toBe(u)
      expect(glyph(name as GlyphName, true)).toBe(a)
    }
  })

  test('the roles are theme keys, never colours', () => {
    for (const v of Object.values(ROLES)) expect(v).toMatch(/^[a-z]+$/)
  })
})
